-- ====== 3. 验证结果 ======
SELECT '=== 职业能力证书成绩统计 ===' AS info;
SELECT 
  COUNT(*) AS total,
  SUM(CASE WHEN theory_score IS NOT NULL AND theory_score != '' THEN 1 ELSE 0 END) AS has_theory,
  SUM(CASE WHEN practical_score IS NOT NULL AND practical_score != '' THEN 1 ELSE 0 END) AS has_practical,
  SUM(CASE WHEN comprehensive_evaluation IS NOT NULL AND comprehensive_evaluation != '' THEN 1 ELSE 0 END) AS has_comprehensive
FROM certificate WHERE cert_type = '职业能力证书';

SELECT '=== 能力等级证书成绩统计 ===' AS info;
SELECT 
  COUNT(*) AS total,
  SUM(CASE WHEN theory_score IS NOT NULL AND theory_score != '' THEN 1 ELSE 0 END) AS has_theory,
  SUM(CASE WHEN practical_score IS NOT NULL AND practical_score != '' THEN 1 ELSE 0 END) AS has_practical,
  SUM(CASE WHEN comprehensive_evaluation IS NOT NULL AND comprehensive_evaluation != '' THEN 1 ELSE 0 END) AS has_comprehensive
FROM certificate WHERE cert_type = '能力等级证书';
